import { defineComponent, h } from '@vue/composition-api';
import { AsyncTemplateConfig } from '@/config/config';
import CommonComponent from '@/config/common';
/** 知识图谱组件 */
export default defineComponent({
  name: 'KnowLedge',
  props: {
    /** 该组件所有值 */
    data: {
      type: Object,
      default: function _default() {
        return {};
      }
    },
    /** 用于指学框的唯一标识 */
    code: {
      type: String
    }
  },
  setup: function setup(props) {
    return function () {
      return h(CommonComponent, {
        "attrs": {
          "margin": AsyncTemplateConfig.plugin.config.margin.generateString()
        }
      }, [h("img", {
        "attrs": {
          "src": props.data.data.url
        },
        "style": {
          verticalAlign: 'middle'
        }
      })]);
    };
  }
});